import json
import sys


def solve(lines):
    sys.setrecursionlimit(100000)
    ALLOWED = {'Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias', 'Phony'}
    blocks = []
    cur = None
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            continue
        tok = line.split()
        if tok[0] == 'TARGET':
            if len(tok) != 2:
                return 'PARSE_ERROR'
            cur = {'kind': 'T', 'name': tok[1], 'id': '', 'dirs': []}
            blocks.append(cur)
        elif tok[0] == 'OVERRIDE':
            if len(tok) != 3:
                return 'PARSE_ERROR'
            cur = {'kind': 'O', 'name': tok[1], 'id': tok[2], 'dirs': []}
            blocks.append(cur)
        elif '=' in line:
            if line.count('=') != 1 or cur is None:
                return 'PARSE_ERROR'
            k, v = line.split('=', 1)
            k = k.strip()
            v = v.strip()
            if k not in ALLOWED:
                return 'PARSE_ERROR'
            if k == 'Phony':
                if v not in ('yes', 'no'):
                    return 'PARSE_ERROR'
                cur['dirs'].append(('Phony', v))
            else:
                cur['dirs'].append((k, v.split()))
        else:
            return 'PARSE_ERROR'

    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    for b in blocks:
        find(b['name'])
        for k, vals in b['dirs']:
            if k == 'Alias':
                for a in vals:
                    union(b['name'], a)

    def canon(x):
        return find(x)

    universe = []
    idx = {}

    def add(x):
        c = canon(x)
        if c not in idx:
            idx[c] = len(universe)
            universe.append(c)

    for b in blocks:
        add(b['name'])
        for k, vals in b['dirs']:
            if k != 'Phony':
                for v in vals:
                    add(v)

    order_blocks = [b for b in blocks if b['kind'] == 'T'] + \
        sorted([b for b in blocks if b['kind'] == 'O'], key=lambda b: b['id'])
    rec = {}
    for b in order_blocks:
        c = canon(b['name'])
        r = rec.setdefault(c, {'Depends': set(), 'Before': set(), 'After': set(),
                               'Needs': set(), 'Requires': set(), 'Phony': 'no'})
        for k, vals in b['dirs']:
            if k == 'Phony':
                r['Phony'] = vals
            elif k != 'Alias':
                r[k].update(canon(x) for x in vals)

    edges = set()
    for u, r in rec.items():
        for x in r['Depends']:
            edges.add((x, u))
        for y in r['Before']:
            edges.add((u, y))
        for z in r['After']:
            edges.add((z, u))
        for w in r['Needs']:
            edges.add((u, w))
        for v in r['Requires']:
            edges.add((u, v))

    adj = {n: [] for n in universe}
    for a, b in edges:
        adj[a].append(b)

    index = {}
    low = {}
    onst = set()
    st = []
    comps = []
    counter = [0]

    def strong(v):
        index[v] = low[v] = counter[0]
        counter[0] += 1
        st.append(v)
        onst.add(v)
        for w in adj[v]:
            if w not in index:
                strong(w)
                low[v] = min(low[v], low[w])
            elif w in onst:
                low[v] = min(low[v], index[w])
        if low[v] == index[v]:
            comp = []
            while True:
                w = st.pop()
                onst.discard(w)
                comp.append(w)
                if w == v:
                    break
            comps.append(comp)

    for n in universe:
        if n not in index:
            strong(n)

    comp_of = {}
    for i, c in enumerate(comps):
        for n in c:
            comp_of[n] = i

    cycles = []
    for c in comps:
        if len(c) >= 2 or (len(c) == 1 and c[0] in adj[c[0]]):
            cycles.append(sorted(c))
    cycles.sort()

    cadj = [set() for _ in comps]
    indeg = [0] * len(comps)
    for a, b in edges:
        ca, cb = comp_of[a], comp_of[b]
        if ca != cb and cb not in cadj[ca]:
            cadj[ca].add(cb)
            indeg[cb] += 1

    members = [sorted(c) for c in comps]
    first = [min(idx[n] for n in c) for c in comps]
    rep = [m[0] for m in members]
    queue = sorted([i for i in range(len(comps)) if indeg[i] == 0],
                   key=lambda i: first[i])
    order = []
    while queue:
        i = queue.pop(0)
        order.extend(members[i])
        newly = []
        for j in cadj[i]:
            indeg[j] -= 1
            if indeg[j] == 0:
                newly.append(j)
        queue.extend(newly)
        queue.sort(key=lambda k: rep[k])

    return json.dumps({'order': order, 'cycles': cycles}, separators=(',', ':'))
